def get_doctor_name(email: str) -> str:
    """Returns official doctor name for a given email."""
    if not email:
        return "Sayın Hekimimiz"
    clean_email = email.lower().strip()
    if clean_email in MASTER_DOCTORS_REGISTRY:
        return MASTER_DOCTORS_REGISTRY[clean_email]
    
    # Fallback to capitalized email prefix
    prefix = clean_email.split("@")[0].capitalize()
    return f"Dr. {prefix}"

def is_doctor_allowed(email: str) -> bool:
    """Checks if email is registered in authorized doctor whitelist."""
    if not email:
        return False
    return email.lower().strip() in MASTER_DOCTORS_REGISTRY
